import{_ as a,o as n,c as i,a as p}from"./app.DkoUFz-u.js";const m=JSON.parse('{"title":"【nvm】 使用问题汇总，来这找就对了","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/engineering/package/nvm.md","filePath":"frontend/engineering/package/nvm.md"}'),_={name:"frontend/engineering/package/nvm.md"};function e(l,s,h,t,c,o){return n(),i("div",null,[...s[0]||(s[0]=[p(`<h1 id="【nvm】-使用问题汇总-来这找就对了" tabindex="-1">【nvm】 使用问题汇总，来这找就对了 <a class="header-anchor" href="#【nvm】-使用问题汇总-来这找就对了" aria-label="Permalink to &quot;【nvm】 使用问题汇总，来这找就对了&quot;">​</a></h1><p>鉴于国内全网没有文章提到这个问题，希望能帮到你，有问题也可以评论区讨论。主要针对linux和macos的问题，windows环境的解决办法网上自己百度吧到处都是</p><h2 id="_1-如果安装完nvm-运行命令行出现找不到nvm" tabindex="-1">1. 如果安装完nvm 运行命令行出现找不到nvm <a class="header-anchor" href="#_1-如果安装完nvm-运行命令行出现找不到nvm" aria-label="Permalink to &quot;1. 如果安装完nvm 运行命令行出现找不到nvm&quot;">​</a></h2><p>正常安装完路径都是直接添加到shell脚本里的，但是也经常出现shell脚本里没有的情况。即找不到nvm 的文件地址，需手动添加</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># 进入.zshrc 或 .bashrc，具体看你使用何种shell</span></span>
<span class="line"><span class="__shiki_1t8gfj">vi</span><span class="__shiki_mdbnqw"> ~/.zshrc</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd"># 申明文件地址 </span></span>
<span class="line"><span class="__shiki_21nrsd"># 进入后添加到末尾保存退出</span></span>
<span class="line"><span class="__shiki_1itgoe">export</span><span class="__shiki_140thh"> NVM_DIR</span><span class="__shiki_1itgoe">=</span><span class="__shiki_mdbnqw">&quot;</span><span class="__shiki_140thh">$HOME</span><span class="__shiki_mdbnqw">/.nvm&quot;</span></span>
<span class="line"><span class="__shiki_140thh">[ </span><span class="__shiki_1itgoe">-s</span><span class="__shiki_mdbnqw"> &quot;</span><span class="__shiki_140thh">$NVM_DIR</span><span class="__shiki_mdbnqw">/nvm.sh&quot;</span><span class="__shiki_140thh"> ] &amp;&amp; </span><span class="__shiki_1t8gfj">\\.</span><span class="__shiki_mdbnqw"> &quot;</span><span class="__shiki_140thh">$NVM_DIR</span><span class="__shiki_mdbnqw">/nvm.sh&quot;</span><span class="__shiki_21nrsd">  # This loads nvm</span></span>
<span class="line"><span class="__shiki_140thh">[ </span><span class="__shiki_1itgoe">-s</span><span class="__shiki_mdbnqw"> &quot;</span><span class="__shiki_140thh">$NVM_DIR</span><span class="__shiki_mdbnqw">/bash_completion&quot;</span><span class="__shiki_140thh"> ] &amp;&amp; </span><span class="__shiki_1t8gfj">\\.</span><span class="__shiki_mdbnqw"> &quot;</span><span class="__shiki_140thh">$NVM_DIR</span><span class="__shiki_mdbnqw">/bash_completion&quot;</span><span class="__shiki_21nrsd">  # This loads nvm bash_completion，macos如果通过brew安装nvm不需要这一行</span></span></code></pre></div><h2 id="_2-nvm-list-remote-出现iojs版本号而不是node版本号" tabindex="-1">2. nvm list-remote 出现iojs版本号而不是node版本号 <a class="header-anchor" href="#_2-nvm-list-remote-出现iojs版本号而不是node版本号" aria-label="Permalink to &quot;2. nvm list-remote 出现iojs版本号而不是node版本号&quot;">​</a></h2><p>iojs版本号 为早起node的一个社区分支，早已弃用，为什么会出现，是因为nvm 官方源的https证书到期了，所以只要更换为http地址即可。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># 进入.zshrc 或 .bashrc，具体看你使用何种shell</span></span>
<span class="line"><span class="__shiki_1t8gfj">vi</span><span class="__shiki_mdbnqw"> ~/.zshrc</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd"># 更换源</span></span>
<span class="line"><span class="__shiki_21nrsd"># 进入后添加到末尾保存退出</span></span>
<span class="line"><span class="__shiki_1itgoe">export</span><span class="__shiki_140thh"> NVM_NODEJS_ORG_MIRROR</span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh">http://nodejs.org/dist</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd"># 这时候会列出正确的node版本列表</span></span>
<span class="line"><span class="__shiki_1t8gfj">nvm</span><span class="__shiki_mdbnqw"> list-remote</span></span></code></pre></div>`,8)])])}const r=a(_,[["render",e]]);export{m as __pageData,r as default};
